CREATE OR REPLACE FUNCTION public.enforce_import_run_ownership()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$
BEGIN
  IF NEW.account_id IS NOT NULL AND NOT EXISTS (
    SELECT 1 FROM trading_accounts WHERE id = NEW.account_id AND user_id = NEW.user_id
  ) THEN
    RAISE EXCEPTION USING ERRCODE = '23514', CONSTRAINT = 'import_runs_account_owner', MESSAGE = 'Import Run Account must belong to the same user.';
  END IF;
  RETURN NEW;
END;
$function$

CREATE OR REPLACE FUNCTION public.enforce_import_run_row_ownership()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$
BEGIN
  IF NOT EXISTS (SELECT 1 FROM import_runs WHERE id = NEW.import_run_id AND user_id = NEW.user_id) THEN
    RAISE EXCEPTION USING ERRCODE = '23514', CONSTRAINT = 'import_run_rows_run_owner', MESSAGE = 'Import Run row must belong to the Run owner.';
  END IF;
  IF NEW.trade_id IS NOT NULL AND NOT EXISTS (SELECT 1 FROM trades WHERE id = NEW.trade_id AND user_id = NEW.user_id) THEN
    RAISE EXCEPTION USING ERRCODE = '23514', CONSTRAINT = 'import_run_rows_trade_owner', MESSAGE = 'Imported Trade must belong to the Run owner.';
  END IF;
  RETURN NEW;
END;
$function$

CREATE OR REPLACE FUNCTION public.update_updated_at_column()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$
BEGIN
  NEW.updated_at = NOW();
  RETURN NEW;
END;
$function$

CREATE OR REPLACE FUNCTION public.validate_daily_review_details_context()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$
DECLARE
  linked_entry journal_entries%ROWTYPE;
BEGIN
  SELECT * INTO linked_entry
  FROM journal_entries
  WHERE id = NEW.journal_entry_id
    AND user_id = NEW.user_id;

  IF NOT FOUND THEN
    RAISE EXCEPTION USING
      ERRCODE = '23514',
      MESSAGE = 'Daily Review ownership is inconsistent.',
      CONSTRAINT = 'daily_review_details_journal_owner';
  END IF;

  IF linked_entry.entry_type <> 'daily_review' THEN
    RAISE EXCEPTION USING
      ERRCODE = '23514',
      MESSAGE = 'Daily Review details require a daily_review Journal entry.',
      CONSTRAINT = 'daily_review_details_journal_type';
  END IF;

  IF linked_entry.entry_date <> NEW.review_date THEN
    RAISE EXCEPTION USING
      ERRCODE = '23514',
      MESSAGE = 'Daily Review date must match its Journal entry.',
      CONSTRAINT = 'daily_review_details_review_date_match';
  END IF;

  RETURN NEW;
END;
$function$

CREATE OR REPLACE FUNCTION public.validate_investment_portfolio_account_context()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$
DECLARE
  account_owner UUID;
  account_currency TEXT;
BEGIN
  IF NEW.trading_account_id IS NULL THEN
    RETURN NEW;
  END IF;

  SELECT a.user_id, a.base_currency
    INTO account_owner, account_currency
  FROM trading_accounts a
  WHERE a.id = NEW.trading_account_id;

  IF NOT FOUND OR account_owner <> NEW.user_id THEN
    RAISE EXCEPTION USING ERRCODE = '23514',
      CONSTRAINT = 'investment_portfolios_trading_account_owner',
      MESSAGE = 'Investment Portfolio and Trading Account ownership must match.';
  END IF;
  IF account_currency <> NEW.base_currency THEN
    RAISE EXCEPTION USING ERRCODE = '23514',
      CONSTRAINT = 'investment_portfolios_trading_account_currency_match',
      MESSAGE = 'Investment Portfolio currency must match Trading Account base currency.';
  END IF;
  RETURN NEW;
END;
$function$

CREATE OR REPLACE FUNCTION public.validate_investment_price_context()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$
DECLARE
  instrument_currency TEXT;
BEGIN
  SELECT i.currency INTO instrument_currency
  FROM investment_instruments i
  WHERE i.id = NEW.instrument_id AND i.user_id = NEW.user_id;
  IF NOT FOUND THEN
    RAISE EXCEPTION USING ERRCODE = '23514', CONSTRAINT = 'investment_prices_instrument_owner',
      MESSAGE = 'Investment Price and Instrument ownership must match.';
  END IF;
  IF NEW.currency <> instrument_currency THEN
    RAISE EXCEPTION USING ERRCODE = '23514', CONSTRAINT = 'investment_prices_instrument_currency_match',
      MESSAGE = 'Investment Price currency must match Instrument currency.';
  END IF;
  RETURN NEW;
END;
$function$

CREATE OR REPLACE FUNCTION public.validate_investment_transaction_context()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$
DECLARE
  portfolio_currency TEXT;
  linked_account_status TEXT;
  instrument_currency TEXT;
BEGIN
  SELECT p.base_currency, a.status
    INTO portfolio_currency, linked_account_status
  FROM investment_portfolios p
  LEFT JOIN trading_accounts a
    ON a.id = p.trading_account_id AND a.user_id = p.user_id
  WHERE p.id = NEW.portfolio_id AND p.user_id = NEW.user_id;

  IF NOT FOUND THEN
    RAISE EXCEPTION USING ERRCODE = '23514', CONSTRAINT = 'investment_transactions_portfolio_owner',
      MESSAGE = 'Investment Transaction and Portfolio ownership must match.';
  END IF;
  IF linked_account_status IS NOT NULL AND linked_account_status <> 'active' THEN
    RAISE EXCEPTION USING ERRCODE = '23514', CONSTRAINT = 'investment_transactions_linked_account_active',
      MESSAGE = 'An inactive or archived linked Account cannot receive new Investment Transactions.';
  END IF;
  IF NEW.currency <> portfolio_currency THEN
    RAISE EXCEPTION USING ERRCODE = '23514', CONSTRAINT = 'investment_transactions_portfolio_currency_match',
      MESSAGE = 'Investment Transaction currency must match Portfolio base currency.';
  END IF;
  IF NEW.instrument_id IS NOT NULL THEN
    SELECT i.currency INTO instrument_currency
    FROM investment_instruments i
    WHERE i.id = NEW.instrument_id AND i.user_id = NEW.user_id;
    IF NOT FOUND THEN
      RAISE EXCEPTION USING ERRCODE = '23514', CONSTRAINT = 'investment_transactions_instrument_owner',
        MESSAGE = 'Investment Transaction and Instrument ownership must match.';
    END IF;
    IF instrument_currency <> portfolio_currency THEN
      RAISE EXCEPTION USING ERRCODE = '23514', CONSTRAINT = 'investment_transactions_instrument_currency_match',
        MESSAGE = 'Instrument currency must match Portfolio base currency.';
    END IF;
  END IF;
  RETURN NEW;
END;
$function$

CREATE OR REPLACE FUNCTION public.validate_trade_managed_classification()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$
DECLARE
  linked_setup_strategy UUID;
BEGIN
  IF NEW.setup_id IS NOT NULL AND NEW.strategy_id IS NULL THEN
    RAISE EXCEPTION USING
      ERRCODE = '23514',
      MESSAGE = 'A managed Setup requires a managed Strategy.',
      CONSTRAINT = 'trades_setup_requires_strategy';
  END IF;

  IF NEW.strategy_id IS NOT NULL AND NOT EXISTS (
    SELECT 1 FROM strategies s
    WHERE s.id = NEW.strategy_id AND s.user_id = NEW.user_id
  ) THEN
    RAISE EXCEPTION USING
      ERRCODE = '23514',
      MESSAGE = 'Trade and Strategy ownership must match.',
      CONSTRAINT = 'trades_strategy_owner_match';
  END IF;

  IF NEW.setup_id IS NOT NULL THEN
    SELECT su.strategy_id INTO linked_setup_strategy
    FROM setups su
    WHERE su.id = NEW.setup_id AND su.user_id = NEW.user_id;

    IF NOT FOUND THEN
      RAISE EXCEPTION USING
        ERRCODE = '23514',
        MESSAGE = 'Trade and Setup ownership must match.',
        CONSTRAINT = 'trades_setup_owner_match';
    END IF;
    IF linked_setup_strategy <> NEW.strategy_id THEN
      RAISE EXCEPTION USING
        ERRCODE = '23514',
        MESSAGE = 'The managed Setup must belong to the selected Strategy.',
        CONSTRAINT = 'trades_setup_strategy_match';
    END IF;
  END IF;

  RETURN NEW;
END;
$function$
